mapper.select:
SELECT id, conversation_id, role, content, is_orphaned, created_at FROM message WHERE conversation_id = #{conversationId}
AND is_orphaned = FALSE
ORDER BY created_at ASC

SELECT id, conversation_id, role, content, is_orphaned, created_at
FROM message
WHERE conversation_id = #{conversationId}
  AND id > #{sinceId}
  AND is_orphaned = FALSE
ORDER BY id ASC

SELECT id, conversation_id, role, content, is_orphaned, created_at
FROM message
WHERE conversation_id = #{conversationId}
  AND is_orphaned = FALSE
  AND id < #{beforeMessageId}
ORDER BY created_at ASC

mapper.update:
UPDATE message
SET is_orphaned = TRUE
WHERE conversation_id = #{conversationId}
  AND created_at >= #{pivot}

UPDATE message
SET is_orphaned = TRUE
WHERE id = #{messageId}
